using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Host;
using MiniFramework.Platform;
using MiniFramework.Providers.PlatformMock;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
public sealed class PlatformServiceTests
{
    static OperationContext Wait=>OperationContext.Unlimited();static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    static readonly PlatformLoginOptions User=new PlatformLoginOptions(true);
    sealed class Env
    {
        internal readonly MockPlatformBackend Backend=new MockPlatformBackend();internal readonly PlatformService Service;internal readonly GameContext Context;internal readonly Scope Listeners=new Scope("listeners");
        internal Env(PlatformLimits limits=null,string dependency=null)
        {Service=new PlatformService(Backend,limits,backendModuleId:dependency);Context=new GameContext(new[]{new ModuleRegistration("platform",Service.Dependencies,()=>Service,typeof(IPlatformCapabilities),typeof(IPlatformLifecycle),typeof(IPlatformLogin))},Cleanup);}
        internal MockPlatformSession Session=>Backend.Sessions[0];internal MockPlatformLoginAttempt Attempt=>Session.Attempts[Session.Attempts.Count-1];
        internal async UniTask Start(){Check(await Context.StartAsync(Wait));}
        internal IPlatformLoginOperation Capture(){var r=Service.CaptureLogin(User);Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);return r.Value;}
        internal async UniTask Finish()
        {
            Backend.FailAttemptCleanup=Backend.FailSessionCleanup=Backend.ThrowAttemptCleanup=false;
            foreach(var s in Backend.Sessions){s.CompleteInitialize();foreach(var a in s.Attempts)a.Complete();}
            await Listeners.CloseAsync(Cleanup);var closing=Context.CloseAsync(Wait);
            for(var i=0;i<6;i++){foreach(var s in Backend.Sessions)foreach(var a in s.Attempts)a.Complete();await UniTask.Yield();}
            var result=await closing;if(!result.IsSuccess)result=await Context.RetryCleanupAsync(Cleanup,Wait);Check(result);Assert.AreEqual(0,Context.RetainedModuleCount);
        }
    }
    readonly List<Env> envs=new List<Env>();Env New(PlatformLimits limits=null,string dependency=null){var e=new Env(limits,dependency);envs.Add(e);return e;}
    static void Check(Result result)=>Assert.IsTrue(result.IsSuccess,result.IsSuccess?"":result.Error.Code);
    static async UniTask Frames(int n=4){for(var i=0;i<n;i++)await UniTask.Yield();}
    static FrameworkError Error(string code,ErrorKind kind=ErrorKind.Provider)=>new FrameworkError(kind,code);
    [UnityTearDown] public IEnumerator Teardown()=>UniTask.ToCoroutine(async()=>{Time.timeScale=1;foreach(var e in envs)await e.Finish();envs.Clear();});
    [UnityTest] public IEnumerator ConstructionAndCaptureAreCold()=>UniTask.ToCoroutine(async()=>{var e=New();Assert.AreEqual(0,e.Backend.Sessions.Count);await e.Start();e.Capture();Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator ContextExposesSeparatePlatformDomains()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.IsTrue(e.Context.TryGet<IPlatformCapabilities>(out var caps));Assert.IsTrue(e.Context.TryGet<IPlatformLifecycle>(out var life));Assert.IsTrue(e.Context.TryGet<IPlatformLogin>(out var login));Assert.AreSame(e.Service,caps);Assert.AreSame(e.Service,life);Assert.AreSame(e.Service,login);});
    [UnityTest] public IEnumerator DefaultStartupIsExplicitForegroundMock()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(PlatformState.Ready,e.Service.State);Assert.AreEqual(PlatformVisibility.Foreground,e.Service.Visibility);Assert.AreEqual(PlatformExecutionMode.Mock,e.Service.Descriptor.Mode);Assert.AreEqual(CapabilitySupport.Unsupported,e.Service.Capabilities.Get(PlatformFeature.RewardedAds).Support);});
    [UnityTest] public IEnumerator UnsupportedLoginNeverCreatesAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Startup=new PlatformStartup(MockPlatformBackend.DefaultCapabilities(CapabilitySupport.Unsupported,CapabilityAvailability.Unavailable),PlatformVisibility.Foreground);await e.Start();Assert.AreEqual(ErrorKind.NotSupported,e.Service.CaptureLogin(User).Error.Kind);Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator PermissionDeniedCapabilityIsNotCanceled()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Startup=new PlatformStartup(MockPlatformBackend.DefaultCapabilities(loginAvailability:CapabilityAvailability.PermissionDenied),PlatformVisibility.Foreground);await e.Start();Assert.AreEqual(ErrorKind.PermissionDenied,e.Service.CaptureLogin(User).Error.Kind);});
    [UnityTest] public IEnumerator UnavailableAndUnknownRemainExplicit()=>UniTask.ToCoroutine(async()=>{foreach(var caps in new[]{MockPlatformBackend.DefaultCapabilities(loginAvailability:CapabilityAvailability.Unavailable),new PlatformCapabilities(Array.Empty<PlatformCapability>())}){var e=New();e.Backend.Startup=new PlatformStartup(caps,PlatformVisibility.Foreground);await e.Start();Assert.AreEqual(ErrorKind.Unavailable,e.Service.CaptureLogin(User).Error.Kind);}});
    [UnityTest] public IEnumerator ForegroundConstraintBlocksBackgroundStart()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Startup=new PlatformStartup(MockPlatformBackend.DefaultCapabilities(),PlatformVisibility.Background);await e.Start();Assert.AreEqual(CapabilityAvailability.Unavailable,e.Service.Capabilities.Get(PlatformFeature.LoginCredential).Availability);Assert.AreEqual(ErrorKind.Unavailable,e.Service.CaptureLogin(User).Error.Kind);});
    [UnityTest] public IEnumerator UserGestureConstraintDoesNotInvokeSdk()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(ErrorKind.InvalidArgument,e.Service.CaptureLogin(default).Error.Kind);Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator LoginReturnsCredentialNotAccount()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();var result=await op.WaitAsync(Wait);Assert.IsTrue(result.IsSuccess);Assert.AreEqual("mock-code",result.Value.ReadAuthorizationCode().Value);Assert.AreEqual(op.AttemptId,result.Value.AttemptId);Assert.AreEqual(PlatformExecutionMode.Mock,result.Value.Mode);await Frames();Assert.AreEqual(0,e.Service.PendingCount);});
    [UnityTest] public IEnumerator LoginWaitIsSingleUse()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();await op.WaitAsync(Wait);Assert.AreEqual("platform.login.single_use",(await op.WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Attempt.StartCount);});
    [UnityTest] public IEnumerator PreCanceledLoginNeverCreatesAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var c=new CancellationTokenSource()){c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Capture().WaitAsync(OperationContext.Unlimited(c.Token))).Error.Kind);}Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator ZeroTimeoutNeverStartsSdk()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(default)).Error.Kind);Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator CancellationWinsZeroDeadline()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var c=new CancellationTokenSource()){c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Capture().WaitAsync(new OperationContext(c.Token,TimeSpan.Zero))).Error.Kind);}});
    [UnityTest] public IEnumerator ActualLoginRemainsSingleFlightAfterSuccessCallback()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoginCompletion=true;await e.Start();var first=e.Capture();Assert.IsTrue((await first.WaitAsync(Wait)).IsSuccess);var second=e.Capture();Assert.AreEqual("platform.login.busy",(await second.WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Session.Attempts.Count);Assert.AreEqual(1,e.Service.ActiveAttemptCount);e.Attempt.Complete();await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);});
    [UnityTest] public IEnumerator CanceledLoginRetainsActualWorkAndDiscardsLateCredential()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();using(var c=new CancellationTokenSource()){var op=e.Capture();var task=op.WaitAsync(OperationContext.Unlimited(c.Token));await Frames();c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await task).Error.Kind);Assert.AreEqual(1,e.Attempt.CancelCount);Assert.AreEqual(0,e.Attempt.CleanupCount);var credential=e.Attempt.PublishSuccess();e.Attempt.Complete();await Frames();Assert.IsTrue(credential.IsDisposed);Assert.AreEqual(PlatformLoginState.Canceled,op.State);Assert.AreEqual(0,e.Service.PendingCount);}});
    [UnityTest] public IEnumerator TimedOutLoginDoesNotPublishLatePayload()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);var credential=e.Attempt.PublishSuccess();e.Attempt.Complete();await Frames();Assert.IsTrue(credential.IsDisposed);Assert.AreEqual(0,e.Service.HeldCredentialCount);});
    [UnityTest] public IEnumerator PausedTimeScaleDoesNotBlockDeadlineOrMailbox()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();Time.timeScale=0;var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,2,PlatformLifecycleKind.Shown));await Frames();Assert.AreEqual(PlatformVisibility.Foreground,e.Service.Visibility);e.Attempt.Complete();});
    [UnityTest] public IEnumerator DuplicateSameCredentialCannotRevokeAcceptedValue()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoginCompletion=true;await e.Start();var result=await e.Capture().WaitAsync(Wait);e.Attempt.PublishAgain(result.Value);await Frames();Assert.IsTrue(result.Value.ReadAuthorizationCode().IsSuccess);Assert.AreEqual(1,e.Service.HeldCredentialCount);e.Attempt.Complete();});
    [UnityTest] public IEnumerator DuplicateNewCredentialIsDiscarded()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoginCompletion=true;await e.Start();await e.Capture().WaitAsync(Wait);var duplicate=e.Attempt.PublishSuccess("duplicate-secret");await Frames();Assert.IsTrue(duplicate.IsDisposed);Assert.AreEqual(1,e.Service.HeldCredentialCount);e.Attempt.Complete();});
    [UnityTest] public IEnumerator WrongAttemptCannotCompleteCurrentLogin()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var op=e.Capture();var task=op.WaitAsync(Wait);var wrong=e.Attempt.PublishSuccess(attemptId:"another-attempt");await Frames();Assert.IsTrue(wrong.IsDisposed);Assert.AreEqual(UniTaskStatus.Pending,task.Status);e.Attempt.PublishSuccess();e.Attempt.Complete();Assert.IsTrue((await task).IsSuccess);});
    [UnityTest] public IEnumerator WrongGenerationCannotEnterNewSession()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var task=e.Capture().WaitAsync(Wait);var old=e.Attempt.PublishSuccess(generation:"old-generation");await Frames();Assert.IsTrue(old.IsDisposed);Assert.AreEqual(UniTaskStatus.Pending,task.Status);e.Attempt.PublishSuccess();e.Attempt.Complete();Assert.IsTrue((await task).IsSuccess);});
    [UnityTest] public IEnumerator MockCannotPublishNativeCredential()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var task=e.Capture().WaitAsync(Wait);var forged=e.Attempt.PublishSuccess(mode:PlatformExecutionMode.Native);Assert.AreEqual(ErrorKind.Integrity,(await task).Error.Kind);Assert.IsTrue(forged.IsDisposed);e.Attempt.Complete();});
    [UnityTest] public IEnumerator ExpiredCallbackCredentialIsRejected()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var task=e.Capture().WaitAsync(Wait);var expired=e.Attempt.PublishSuccess(expiry:DateTimeOffset.UtcNow.AddMinutes(-1));Assert.AreEqual(ErrorKind.Integrity,(await task).Error.Kind);Assert.IsTrue(expired.IsDisposed);e.Attempt.Complete();});
    [UnityTest] public IEnumerator LoginErrorsRetainCategoryAndRedactMessage()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.LoginError=new FrameworkError(ErrorKind.PermissionDenied,"platform.mock.denied","secret-native-message");await e.Start();var r=await e.Capture().WaitAsync(Wait);Assert.AreEqual(ErrorKind.PermissionDenied,r.Error.Kind);Assert.AreEqual("",r.Error.Message);Assert.IsFalse(r.Error.Code.Contains("secret-native-message"));});
    [UnityTest] public IEnumerator ActualTerminalWithoutCallbackIsExplicitFailure()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;await e.Start();Assert.AreEqual("platform.login.no_callback",(await e.Capture().WaitAsync(Wait)).Error.Code);await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);});
    [UnityTest] public IEnumerator TerminalFenceWaitsForEarlierQueuedResult()=>UniTask.ToCoroutine(async()=>{var e=New(new PlatformLimits(queueCapacity:16,callbacksPerFrame:1));await e.Start();for(var i=1;i<=6;i++)e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,i,PlatformLifecycleKind.MemoryWarning));var op=e.Capture();var result=await op.WaitAsync(Wait);Assert.IsTrue(result.IsSuccess);await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);});
    [UnityTest] public IEnumerator WorkerThreadCallbacksOnlyNotifyOnMainThread()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var main=Thread.CurrentThread.ManagedThreadId;var observed=0;Assert.IsTrue(e.Service.SubscribeLifecycle(e.Listeners,"worker",_=>observed=Thread.CurrentThread.ManagedThreadId).IsSuccess);await Task.Run(()=>e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden)));await UniTask.SwitchToMainThread();await Frames();Assert.AreEqual(main,observed);});
    [UnityTest] public IEnumerator DuplicateAndOutOfOrderVisibilityAreNotReplayed()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var count=0;e.Service.SubscribeLifecycle(e.Listeners,"life",_=>count++);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,2,PlatformLifecycleKind.Hidden));e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,2,PlatformLifecycleKind.Shown));e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Shown));e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,3,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(1,count);Assert.AreEqual(PlatformVisibility.Background,e.Service.Visibility);});
    [UnityTest] public IEnumerator ShowRestoresAvailabilityWithoutGameHostPump()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var host=new HostScheduler()){host.SetPaused(true);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(CapabilityAvailability.Unavailable,e.Service.Capabilities.Get(PlatformFeature.LoginCredential).Availability);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,2,PlatformLifecycleKind.Shown));await Frames();Assert.IsTrue(host.IsPaused);Assert.IsTrue(e.Service.Capabilities.Get(PlatformFeature.LoginCredential).IsUsable);Assert.IsTrue((await e.Capture().WaitAsync(Wait)).IsSuccess);}});
    [UnityTest] public IEnumerator HideCancelsForegroundOnlyAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var task=e.Capture().WaitAsync(Wait);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));Assert.AreEqual("platform.login.hidden",(await task).Error.Code);Assert.AreEqual(1,e.Attempt.CancelCount);e.Attempt.Complete();});
    [UnityTest] public IEnumerator CapabilityChangesUseOrderedSnapshotAndEvent()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var count=0;e.Service.SubscribeCapabilities(e.Listeners,"caps",_=>count++);var denied=MockPlatformBackend.DefaultCapabilities(loginAvailability:CapabilityAvailability.PermissionDenied);e.Session.Publish(PlatformCallback.CapabilitiesChanged(e.Service.Generation,2,denied));e.Session.Publish(PlatformCallback.CapabilitiesChanged(e.Service.Generation,1,MockPlatformBackend.DefaultCapabilities()));await Frames();Assert.AreEqual(1,count);Assert.AreEqual(ErrorKind.PermissionDenied,e.Service.CaptureLogin(User).Error.Kind);});
    [UnityTest] public IEnumerator ColdLoginRechecksCapabilitiesBeforeSdkCall()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();e.Session.Publish(PlatformCallback.CapabilitiesChanged(e.Service.Generation,1,MockPlatformBackend.DefaultCapabilities(loginAvailability:CapabilityAvailability.PermissionDenied)));await Frames();Assert.AreEqual(ErrorKind.PermissionDenied,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator ClosedSubscriberScopeStopsNotifications()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var count=0;e.Service.SubscribeLifecycle(e.Listeners,"scope",_=>count++);await e.Listeners.CloseAsync(Cleanup);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(0,count);Assert.AreEqual(0,e.Service.ReadDiagnostics().Listeners);});
    [UnityTest] public IEnumerator ThrowingListenerDoesNotBlockOtherListeners()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var count=0;e.Service.SubscribeLifecycle(e.Listeners,"throws",_=>throw new Exception());e.Service.SubscribeLifecycle(e.Listeners,"other",_=>count++);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(1,count);Assert.AreEqual(1,e.Service.CallbackErrors);});
    [UnityTest] public IEnumerator ClosingInsideListenerStopsRemainingDispatch()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var calls=0;e.Service.SubscribeLifecycle(e.Listeners,"close",_=>e.Context.CloseAsync(Wait).Forget());e.Service.SubscribeLifecycle(e.Listeners,"late",_=>calls++);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(0,calls);});
    [UnityTest] public IEnumerator QueueLimitRejectsAndDisposesProducerPayload()=>UniTask.ToCoroutine(async()=>{var e=New(new PlatformLimits(queueCapacity:1,callbacksPerFrame:1));await e.Start();Assert.IsTrue(e.Session.Publish(PlatformCallback.LifecycleChanged(e.Service.Generation,1,PlatformLifecycleKind.MemoryWarning)));var credential=new PlatformLoginCredential("editor-mock","unknown",PlatformExecutionMode.Mock,"private");Assert.IsFalse(e.Session.Publish(PlatformCallback.Login(e.Service.Generation,"unknown",Result<PlatformLoginCredential>.Success(credential))));Assert.IsTrue(credential.IsDisposed);Assert.AreEqual(1,e.Service.RejectedCallbacks);});
    [UnityTest] public IEnumerator StopDiscardsQueuedPayloadsAndRevokesAcceptedCredential()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var credential=(await e.Capture().WaitAsync(Wait)).Value;var queued=new PlatformLoginCredential("editor-mock","unknown",PlatformExecutionMode.Mock,"queued");e.Session.Publish(PlatformCallback.Login(e.Service.Generation,"unknown",Result<PlatformLoginCredential>.Success(queued)));Check(await e.Context.CloseAsync(Wait));Assert.IsTrue(credential.IsDisposed);Assert.IsTrue(queued.IsDisposed);Assert.AreEqual(0,e.Service.QueuedCount);});
    [UnityTest] public IEnumerator ClosedSessionProducerDiscardsLatePayload()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Capture().WaitAsync(Wait);var attempt=e.Attempt;Check(await e.Context.CloseAsync(Wait));var late=attempt.PublishSuccess("late-private");Assert.IsTrue(late.IsDisposed);Assert.AreEqual(0,e.Service.HeldCredentialCount);});
    [UnityTest] public IEnumerator CloseWaitsForActualLoginBeforeSessionCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;await e.Start();var task=e.Capture().WaitAsync(Wait);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(0,e.Session.CleanupCount);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.Complete();Check(await close);Assert.AreEqual(ErrorKind.Canceled,(await task).Error.Kind);Assert.AreEqual(1,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator AttemptCleanupFailureRetainsSessionUntilExplicitRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.FailAttemptCleanup=true;await e.Start();await e.Capture().WaitAsync(Wait);await Frames();Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);Assert.AreEqual(1,e.Context.RetainedModuleCount);Assert.AreEqual(0,e.Session.CleanupCount);Assert.AreEqual(1,e.Attempt.CleanupCount);e.Backend.FailAttemptCleanup=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator SessionCleanupFailureExplicitlyRetriesOnlyCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Backend.FailSessionCleanup=true;Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);e.Backend.FailSessionCleanup=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,e.Session.CleanupCount);Assert.AreEqual(1,e.Session.InitializeCount);});
    [UnityTest] public IEnumerator CancelFailureDoesNotReleaseRunningSdk()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoReply=false;e.Backend.HoldLoginCompletion=true;e.Backend.FailCancel=true;await e.Start();var op=e.Capture();using(var c=new CancellationTokenSource()){var task=op.WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();await task;Assert.IsTrue(op.CancelError.HasValue);Assert.AreEqual(1,e.Service.ActiveAttemptCount);e.Attempt.Complete();await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);}});
    [UnityTest] public IEnumerator LateInitializationCannotReturnReadyAfterCancellation()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldInitialize=true;using(var c=new CancellationTokenSource()){var start=e.Context.StartAsync(OperationContext.Unlimited(c.Token));await Frames();c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await start).Error.Kind);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(0,e.Session.CleanupCount);e.Session.CompleteInitialize();Check(await close);Assert.AreEqual(PlatformState.Closed,e.Service.State);}});
    [UnityTest] public IEnumerator InitializeFailureRollsBackSessionWithoutLogin()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.InitializeError=Error("platform.mock.init");Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);await e.Context.CloseAsync(Wait);Assert.AreEqual(1,e.Session.CleanupCount);Assert.AreEqual(0,e.Session.Attempts.Count);});
    [UnityTest] public IEnumerator MissingBackendDependencyFailsBeforeOpen()=>UniTask.ToCoroutine(async()=>{var e=New(dependency:"missing");Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Sessions.Count);});
    [UnityTest] public IEnumerator UnrelatedStartExceptionIsProviderNotCanceled()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.ThrowStart=true;await e.Start();Assert.AreEqual(ErrorKind.Provider,(await e.Capture().WaitAsync(Wait)).Error.Kind);await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);});
