    [UnityTest] public IEnumerator HeldCredentialLimitRechecksColdOperations()=>UniTask.ToCoroutine(async()=>{var e=New(new PlatformLimits(maxCredentials:1));await e.Start();var first=e.Capture();var second=e.Capture();var credential=(await first.WaitAsync(Wait)).Value;await Frames();Assert.AreEqual("platform.login.capacity",(await second.WaitAsync(Wait)).Error.Code);credential.Dispose();Assert.IsTrue(e.Service.CaptureLogin(User).IsSuccess);});
    [UnityTest] public IEnumerator OldContextCannotDeliverIntoNewContext()=>UniTask.ToCoroutine(async()=>{var first=New();await first.Start();var old=first.Session;var generation=first.Service.Generation;Check(await first.Context.CloseAsync(Wait));var second=New();await second.Start();var count=0;second.Service.SubscribeLifecycle(second.Listeners,"generation",_=>count++);Assert.AreNotEqual(generation,second.Service.Generation);Assert.IsFalse(old.Publish(PlatformCallback.LifecycleChanged(generation,1,PlatformLifecycleKind.Hidden)));second.Session.Publish(PlatformCallback.LifecycleChanged(generation,2,PlatformLifecycleKind.Hidden));await Frames();Assert.AreEqual(0,count);Assert.AreEqual(PlatformVisibility.Foreground,second.Service.Visibility);});
    [UnityTest] public IEnumerator RepeatedLoginAndCloseReturnCountersToZero()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();for(var i=0;i<10;i++){var credential=(await e.Capture().WaitAsync(Wait)).Value;credential.Dispose();await Frames();}Check(await e.Context.CloseAsync(Wait));var c=e.Service.ReadDiagnostics();Assert.AreEqual(0,c.PendingOperations);Assert.AreEqual(0,c.QueuedCallbacks);Assert.AreEqual(0,c.Listeners);Assert.AreEqual(0,e.Service.HeldCredentialCount);});
}
